using Fanex.Tarus.Admin.Entities;
using Fanex.Tarus.Admin.ViewModel;
using Sunplus.Accounting.Business.BootStrappers;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Configurations;
using Sunplus.Accounting.DataAccess;
using Sunplus.Accounting.Entities;
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;

namespace Sunplus.Accounting.Business
{
    public class Helper : IHelper
    {
        private IHelperDAO _helperDao;

        public Helper()
        {
            _helperDao = CommonBootStrapper.Locator.GetInstance<IHelperDAO>();
        }

        public Helper(IHelperDAO helperDao)
        {
            _helperDao = helperDao;
        }

        public List<SiteViewModel> GetSites(Enumerations.AccountingSystem system)
        {
            var listSiteDTO = new List<SiteViewModel>();
            var result = _helperDao.GetSites(system);
            var listCredit = new List<Entities.SiteEntity>();
            foreach (DataRow row in result.Rows)
            {
                if (row["islicensee"].ToString() == "False")
                {
                    var credit = new Entities.SiteEntity();
                    credit.SiteId = int.Parse(row["siteId"].ToString());
                    credit.SiteName = row["site"].ToString();
                    credit.SiteLabel = row["sitelabel"].ToString();
                    listCredit.Add(credit);
                }
            }

            listCredit
                .GroupBy(p => p.SiteLabel)
               .ToList()
               .ForEach(grp =>
               {
                   if (string.IsNullOrEmpty(grp.Key))
                   {
                       listSiteDTO.AddRange(grp.Select(pt => new SiteViewModel(pt.SiteId.ToString(), pt.SiteName, null)));
                   }
                   else
                   {
                       listSiteDTO.Add(new SiteViewModel(grp.Key, grp.Key, grp.Select(p => new SiteViewModel(p.SiteId.ToString(), p.SiteName, null))));
                   }
               });
            
            return listSiteDTO;
        }

        public List<Site> GetSiteLicensee()
        {
            List<Site> sites = new List<Site>();

            return sites;
        }

        public string[] GetStandardCurrencyList()
        {
            List<string> listStandardCurrencyList = new List<string>();
            var helperCollection = HelperSection.Instance[HelperSection.HelperCollectionType.Currency]["StandardCurrencies"].Items;

            foreach (HelperElement helperElement in helperCollection)
            {
                listStandardCurrencyList.Add(helperElement.Value);
            }

            string[] result = listStandardCurrencyList.ToArray();
            Array.Sort(result);
            return result;
        }
    }
}